def sieve_of_eratosthenes(limit):
    primes = [True] * (limit + 1)
    primes[0] = primes[1] = False
    p = 2
    while (p * p <= limit):
        if primes[p]:
            for i in range(p * p, limit + 1, p):
                primes[i] = False
        p += 1

    count = 0
    for p in range(2, limit + 1):
        if primes[p]:
            count += 1
    return count

print(sieve_of_eratosthenes(2000))
